<?php
namespace NexoCursos;
defined('ABSPATH') || exit;
final class PortalCourses {
    private const TYPES=['nexo_topic'=>'Tópico','nexo_lesson'=>'Aula','nexo_quiz'=>'Teste'];
    public static function mutate(string $action,array $d) {
        if($action==='content_save'||$action==='content_archive'){return self::save_content($action,$d);}
        $id=Portal::id($d,'course_id');$course=$id?Portal::course($id):null;if(is_wp_error($course)){return $course;}if(!$id&&!Portal::all_courses()){return new \WP_Error('forbidden','Somente a coordenação pode criar cursos.');}
        if($action==='course_archive'){
            if(!$id){return new \WP_Error('course','Escolha um curso.');}$saved=wp_update_post(['ID'=>$id,'post_status'=>'draft'],true);return is_wp_error($saved)?$saved:['message'=>'Curso voltou para rascunho. Matrículas e histórico foram preservados.','view'=>'courses'];
        }
        $title=Portal::text($d,'title');$mode=Portal::text($d,'nexo_mode');$pricing=Portal::text($d,'nexo_enrollment_mode');$status=Portal::text($d,'status');
        if(!$title||mb_strlen($title)>180||!in_array($mode,['online','erp'],true)||!in_array($pricing,['free','paid','manual'],true)||!in_array($status,['draft','publish','private'],true)){return new \WP_Error('fields','Confira título, formato, inscrição e situação do curso.');}
        $price=Portal::text($d,'nexo_price');$price=function_exists('wc_format_decimal')?wc_format_decimal($price):str_replace(',','.',$price);
        if($pricing==='paid'&&(!class_exists('WooCommerce')||!is_numeric($price)||(float)$price<=0)){return new \WP_Error('price','Cursos pagos precisam de um preço maior que zero e das vendas ativas na plataforma.');}
        $raw=['start'=>Portal::text($d,'nexo_start_date'),'end'=>Portal::text($d,'nexo_end_date'),'frequency'=>Portal::text($d,'nexo_frequency')?:'none','interval'=>Portal::id($d,'nexo_interval')?:1,'unit'=>Portal::text($d,'nexo_interval_unit')?:'week','weekdays'=>is_array($d['nexo_weekdays']??null)?$d['nexo_weekdays']:[],'time'=>Portal::text($d,'nexo_session_time'),'duration'=>Portal::id($d,'nexo_session_duration')?:90,'automatic'=>$mode==='erp'&&!empty($d['nexo_generate_sessions'])];
        $schedule=Calendar::validate($raw);$dates=is_wp_error($schedule)?$schedule:Calendar::dates($schedule);if(is_wp_error($dates)){return $dates;}
        $sale_raw=Portal::text($d,'nexo_sale_price');$sale=$sale_raw!==''?(function_exists('wc_format_decimal')?wc_format_decimal($sale_raw):str_replace(',','.',$sale_raw)):'';if($sale!==''&&(!is_numeric($sale)||(float)$sale<0||!is_numeric($price)||(float)$sale>=(float)$price)){return new \WP_Error('sale','O preço promocional deve ser menor que o preço normal.');}
        $meta=['_nexo_sale_price'=>$sale,'_nexo_mode'=>$mode,'_nexo_enrollment_mode'=>$pricing,'_nexo_price'=>is_numeric($price)&&(float)$price>0?(string)$price:'','_nexo_capacity'=>Portal::id($d,'nexo_capacity'),'_nexo_workload'=>Portal::text($d,'nexo_workload'),'_nexo_location'=>Portal::text($d,'nexo_location'),'_nexo_course_color'=>sanitize_hex_color(Portal::text($d,'nexo_course_color'))?:'','_nexo_course_tagline'=>mb_substr(Portal::text($d,'nexo_course_tagline'),0,120),'_nexo_schedule_config'=>$schedule];
        foreach(['start'=>'start_date','end'=>'end_date','frequency'=>'frequency','interval'=>'interval','unit'=>'interval_unit','weekdays'=>'weekdays','time'=>'session_time','duration'=>'session_duration','automatic'=>'generate_sessions'] as $key=>$m){$meta['_nexo_'.$m]=$schedule[$key];}
        if(Portal::all_courses()){$managers=[];foreach(array_slice((array)($d['nexo_manager_ids']??[]),0,500) as $uid){if(is_scalar($uid)&&user_can(absint($uid),'nexo_manage_assigned')){$managers[]=absint($uid);}}$meta['_nexo_manager_ids']=array_values(array_unique($managers));}
        $upload=Portal::upload('course_cover',$id);if(is_wp_error($upload)){return $upload;}
        if($id){delete_post_meta($id,'_nexo_schedule_error');}
        $saved=wp_insert_post(['ID'=>$id,'post_type'=>'nexo_course','post_status'=>$status,'post_title'=>$title,'post_content'=>wp_kses_post(wp_unslash(is_string($d['description']??null)?$d['description']:'')),'post_excerpt'=>sanitize_textarea_field(wp_unslash(is_string($d['excerpt']??null)?$d['excerpt']:'')),'meta_input'=>$meta],true);
        if(is_wp_error($saved)){return $saved;}$id=(int)$saved;if($upload){wp_update_post(['ID'=>$upload,'post_parent'=>$id]);set_post_thumbnail($id,$upload);}elseif(!empty($d['remove_course_cover'])){delete_post_thumbnail($id);}Commerce::sync_product($id);
        $error=get_post_meta($id,'_nexo_product_sync_error',true)?:get_post_meta($id,'_nexo_schedule_error',true);
        return ['message'=>$error?'Curso salvo. '.$error:'Curso salvo. Programação e produto foram atualizados quando aplicáveis.','view'=>'courses','args'=>['course_id'=>$id,'editor'=>'edit']];
    }
    public static function questions(array $rows) {
        if(count($rows)>100){return new \WP_Error('quiz','Use até 100 perguntas por teste.');}$out=[];
        foreach($rows as $raw){if(!is_array($raw)){return new \WP_Error('quiz','Pergunta inválida.');}$text=Portal::text($raw,'question');if(!$text){continue;}$options=[];$correct=-1;if(isset($raw['correct'])&&!is_scalar($raw['correct'])){return new \WP_Error('quiz','Escolha uma alternativa correta válida.');}
            if(!is_array($raw['options']??null)||count($raw['options'])>6){return new \WP_Error('quiz','Use de duas a seis alternativas por pergunta.');}
            foreach($raw['options'] as $index=>$value){if(!is_scalar($value)){return new \WP_Error('quiz','Alternativa inválida.');}$option=sanitize_text_field(wp_unslash((string)$value));if($option===''){continue;}if((string)$index===(string)($raw['correct']??'')){$correct=count($options);}$options[]=$option;}
            if(count($options)<2||$correct<0){return new \WP_Error('quiz','Cada pergunta precisa de duas alternativas e uma resposta correta.');}$out[]=['question'=>$text,'options'=>$options,'correct'=>$correct];
        }return $out;
    }
    private static function save_content(string $action,array $d) {
        $course=Portal::id($d,'course_id');$c=Portal::course($course);if(is_wp_error($c)){return $c;}$id=Portal::id($d,'item_id');$p=$id?get_post($id):null;
        if($id&&(!$p||!isset(self::TYPES[$p->post_type])||(int)get_post_meta($id,'_nexo_course_id',true)!==$course||$p->post_status==='trash')){return new \WP_Error('forbidden','O conteúdo não pertence a este curso.');}
        if($action==='content_archive'){if(!$id){return new \WP_Error('content','Selecione um conteúdo.');}$r=wp_update_post(['ID'=>$id,'post_status'=>'draft'],true);return is_wp_error($r)?$r:['message'=>'Conteúdo movido para rascunho.','view'=>'content','args'=>['course_id'=>$course]];}
        $type=$p?$p->post_type:Portal::text($d,'content_type');$title=Portal::text($d,'title');$status=Portal::text($d,'status');if(!isset(self::TYPES[$type])||!$title||!in_array($status,['draft','publish'],true)){return new \WP_Error('content','Informe o título e escolha um tipo e uma situação válidos.');}
        $topic=Portal::id($d,'nexo_topic_id');if($topic&&(get_post_type($topic)!=='nexo_topic'||(int)get_post_meta($topic,'_nexo_course_id',true)!==$course)){return new \WP_Error('topic','O tópico precisa pertencer ao mesmo curso.');}
        $meta=['_nexo_course_id'=>$course,'_nexo_topic_id'=>$type==='nexo_topic'?0:$topic];
        if($type==='nexo_lesson'){$meta['_nexo_video_url']=esc_url_raw(Portal::text($d,'nexo_video_url'),['http','https']);}
        if($type==='nexo_quiz'){$q=self::questions(is_array($d['nexo_questions']??null)?$d['nexo_questions']:[]);if(is_wp_error($q)){return $q;}if($status==='publish'&&!$q){return new \WP_Error('quiz','Adicione pelo menos uma pergunta antes de publicar o teste.');}$meta['_nexo_questions']=$q;$meta['_nexo_pass_score']=max(0,min(100,(int)Portal::text($d,'nexo_pass_score')));}
        $saved=wp_insert_post(['ID'=>$id,'post_type'=>$type,'post_status'=>$status,'post_title'=>mb_substr($title,0,180),'post_content'=>wp_kses_post(wp_unslash(is_string($d['description']??null)?$d['description']:'')),'menu_order'=>(int)Portal::text($d,'nexo_menu_order'),'meta_input'=>$meta],true);
        return is_wp_error($saved)?$saved:['message'=>'Conteúdo salvo.','view'=>'content','args'=>['course_id'=>$course,'item_id'=>$saved,'editor'=>'edit']];
    }
    public static function render(): void {
        $editor=Portal::text($_GET,'editor');$id=Portal::id($_GET,'course_id');if($editor==='new'||$editor==='edit'){self::editor($id);return;}
        echo '<div class="np-section-actions"><p>Organize cursos presenciais e on-line. Aulas, tópicos e testes são opcionais.</p>'.(Portal::all_courses()?'<a class="np-button" href="'.esc_url(Portal::url('courses',['editor'=>'new'])).'">＋ Criar curso</a>':'').'</div><div class="np-course-list">';
        foreach(Portal::courses() as $c){$students=count(Calendar::enrolled($c->ID));echo '<article class="np-card np-course-tile"><div class="np-tile-image">'.(get_the_post_thumbnail($c->ID,'medium')?:'<span aria-hidden="true">✧</span>').'</div><div><span class="np-badge">'.esc_html($c->post_status==='publish'?'Publicado':'Rascunho / restrito').'</span><h2>'.esc_html($c->post_title).'</h2><p>'.esc_html(get_post_meta($c->ID,'_nexo_mode',true)==='erp'?'Presencial / gestão':'EAD').' · '.absint($students).' aluno(s)</p><div class="np-actions"><a class="np-button" href="'.esc_url(Portal::url('courses',['editor'=>'edit','course_id'=>$c->ID])).'">Editar curso</a><a class="np-button np-secondary" href="'.esc_url(Portal::url('content',['course_id'=>$c->ID])).'">Conteúdos</a><a class="np-text-link" href="'.esc_url(Portal::url('students',['course_id'=>$c->ID])).'">Alunos</a>'.(get_post_meta($c->ID,'_nexo_mode',true)==='erp'?'<a class="np-text-link" href="'.esc_url(Portal::url('classroom',['course_id'=>$c->ID])).'">Chamada</a>':'').'</div></div></article>';}
        echo '</div>';if(!Portal::courses()){echo '<p class="np-empty">Nenhum curso disponível para sua conta.</p>';}
    }
    private static function editor(int $id): void {
        $p=$id?Portal::course($id):null;if(is_wp_error($p)||(!$id&&!Portal::all_courses())){echo '<p class="np-error">Você não pode editar este curso.</p>';return;}
        $get=static fn($key)=>$id?get_post_meta($id,'_nexo_'.$key,true):'';$schedule=$id?Calendar::config($id):['start'=>'','end'=>'','frequency'=>'weekly','interval'=>1,'unit'=>'week','weekdays'=>[],'time'=>'20:00','duration'=>90,'automatic'=>true];
        echo '<a class="np-back" href="'.esc_url(Portal::url('courses')).'">← Todos os cursos</a><section class="np-card"><h2>'.($id?'Editar curso':'Novo curso').'</h2>'.Portal::form('course_save','courses',['course_id'=>$id,'editor'=>'edit']).'<div class="np-form-grid">'.Portal::input('Título do curso','title',$p?$p->post_title:'','text','required maxlength="180"').Portal::select('Situação','status',['draft'=>'Rascunho','publish'=>'Publicado','private'=>'Restrito à equipe'],$p?$p->post_status:'draft').'</div>'.Portal::textarea('Apresentação do curso','description',$p?$p->post_content:'',8).Portal::textarea('Resumo para o catálogo','excerpt',$p?$p->post_excerpt:'',3).'<div class="np-form-grid">'.Portal::select('Formato','nexo_mode',['online'=>'EAD — conteúdo opcional','erp'=>'Gestão / presencial'],$get('mode')?:'online').Portal::select('Inscrição','nexo_enrollment_mode',['free'=>'Gratuita','paid'=>'Paga','manual'=>'Somente matrícula manual'],$id?Commerce::pricing_mode($id):'free').Portal::input('Preço ('.(function_exists('get_woocommerce_currency')?get_woocommerce_currency():'moeda da loja').')','nexo_price',$get('price'),'number','min="0" step="0.01"').Portal::input('Preço promocional (opcional)','nexo_sale_price',$get('sale_price'),'number','min="0" step="0.01"').Portal::input('Carga horária','nexo_workload',$get('workload'),'text','placeholder="Ex.: 20 horas"').Portal::input('Local / unidade','nexo_location',$get('location')).Portal::input('Vagas de referência','nexo_capacity',$get('capacity'),'number','min="0"').Portal::input('Cor do curso (opcional)','nexo_course_color',$get('course_color'),'text','pattern="#[0-9a-fA-F]{6}" placeholder="#071450"').Portal::input('Frase da capa (opcional)','nexo_course_tagline',$get('course_tagline'),'text','maxlength="120"').'</div>'.Portal::image_field('Capa do curso','course_cover',$id?(int)get_post_thumbnail_id($id):0);
        echo '<p class="np-help">Cursos pagos criam o produto automaticamente com título, descrição e capa. Vagas são uma referência; o estoque pode ser definido em Produtos.</p>';
        if(Portal::all_courses()){$assigned=array_map('absint',(array)$get('manager_ids'));echo '<fieldset><legend>Gerentes responsáveis</legend><div class="np-check-grid">';foreach(get_users(['role'=>'nexo_manager','number'=>500,'orderby'=>'display_name']) as $u){echo '<label class="np-check"><input type="checkbox" name="nexo_manager_ids[]" value="'.$u->ID.'" '.checked(in_array((int)$u->ID,$assigned,true),true,false).'>'.esc_html($u->display_name).'</label>';}echo '</div><p class="np-help">A coordenação já pode acompanhar todos os cursos.</p></fieldset>';}
        self::schedule_fields($schedule);echo Portal::button('Salvar curso').'</form></section>';
        if($id){echo '<section class="np-card"><h2>Disponibilidade</h2><p>Voltar para rascunho retira o curso do catálogo e suspende o acesso dos alunos até republicar. Matrículas e histórico são mantidos.</p>'.Portal::form('course_archive','courses',['course_id'=>$id]).Portal::button('Voltar para rascunho','np-secondary').'</form></section>';}
    }
    private static function schedule_fields(array $s): void {
        echo '<fieldset><legend>Datas e programação presencial</legend><div class="np-form-grid">'.Portal::input('Data inicial','nexo_start_date',$s['start'],'date').Portal::input('Data final (inclusive)','nexo_end_date',$s['end'],'date').Portal::select('Frequência','nexo_frequency',['none'=>'Sem geração automática','once'=>'Encontro único','daily'=>'Diário','weekdays'=>'Dias úteis','weekly'=>'Semanal','biweekly'=>'Quinzenal','monthly'=>'Mensal','custom'=>'Intervalo personalizado'],$s['frequency']).Portal::input('Horário de início','nexo_session_time',$s['time'],'time').Portal::input('Duração por aula (minutos)','nexo_session_duration',$s['duration'],'number','min="15" max="720"').Portal::input('Intervalo personalizado','nexo_interval',$s['interval'],'number','min="1" max="52"').Portal::select('Unidade do intervalo','nexo_interval_unit',['day'=>'Dias','week'=>'Semanas','month'=>'Meses'],$s['unit']).'</div><div class="np-check-grid">';
        foreach(['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'] as $i=>$day){echo '<label class="np-check"><input type="checkbox" name="nexo_weekdays[]" value="'.$i.'" '.checked(in_array($i,array_map('intval',$s['weekdays']),true),true,false).'>'.$day.'</label>';}
        echo '</div><p class="np-help">Sem seleção, usa o dia da data inicial. Mensal ajusta para o último dia dos meses curtos.</p><label class="np-check"><input type="checkbox" name="nexo_generate_sessions" value="1" '.checked($s['automatic'],true,false).'> Gerar e atualizar aulas ao salvar, no formato presencial</label><p class="np-help">Encontros passados ou com chamada são preservados ao alterar a programação.</p></fieldset>';
    }
    public static function content(): void {
        $courses=Portal::courses();if(!$courses){echo '<p class="np-empty">Atribua ou crie um curso para organizar seus conteúdos.</p>';return;}$course=Portal::id($_GET,'course_id')?:$courses[0]->ID;$p=Portal::course($course);if(is_wp_error($p)){echo '<p class="np-error">Curso indisponível para sua conta.</p>';return;}
        echo '<form method="get" action="'.esc_url(nexo_page_url('dashboard')).'" class="np-filters">'.Portal::get_fields('content');$options=[];foreach($courses as $c){$options[$c->ID]=$c->post_title;}echo Portal::select('Curso','course_id',$options,$course).Portal::button('Abrir curso','np-secondary').'</form>';
        $id=Portal::id($_GET,'item_id');$editor=Portal::text($_GET,'editor');$item=$id?get_post($id):null;
        if($id&&(!$item||!isset(self::TYPES[$item->post_type])||(int)get_post_meta($id,'_nexo_course_id',true)!==$course)){echo '<p class="np-error">O conteúdo não pertence a este curso.</p>';return;}
        if($editor==='new'||$editor==='edit'){
            echo '<section class="np-card"><h2>'.($id?'Editar conteúdo':'Novo conteúdo').'</h2>'.Portal::form('content_save','content',['course_id'=>$course,'item_id'=>$id,'editor'=>'edit']).'<div class="np-form-grid">'.($id?'<p class="np-badge">'.esc_html(self::TYPES[$item->post_type]).'</p>':Portal::select('Tipo','content_type',self::TYPES,Portal::text($_GET,'type')?:'nexo_lesson')).Portal::input('Título','title',$item?$item->post_title:'','text','required maxlength="180"').Portal::select('Situação','status',['draft'=>'Rascunho','publish'=>'Publicado'],$item?$item->post_status:'draft').Portal::input('Ordem no curso','nexo_menu_order',$item?$item->menu_order:0,'number').'</div>'.Portal::textarea('Conteúdo para o aluno','description',$item?$item->post_content:'',9);
            $topics=[0=>'Sem tópico'];foreach(get_posts(['post_type'=>'nexo_topic','post_status'=>['publish','draft','private'],'numberposts'=>-1,'meta_key'=>'_nexo_course_id','meta_value'=>$course]) as $t){$topics[$t->ID]=$t->post_title;}echo '<div class="np-form-grid">'.Portal::select('Tópico (opcional)','nexo_topic_id',$topics,$id?get_post_meta($id,'_nexo_topic_id',true):0).Portal::input('Vídeo da aula (opcional)','nexo_video_url',$id?get_post_meta($id,'_nexo_video_url',true):'','url','placeholder="https://…"').'</div>';
            echo '<details class="np-quiz-editor" '.(($item&&$item->post_type==='nexo_quiz')||Portal::text($_GET,'type')==='nexo_quiz'?'open':'').'><summary>Perguntas do teste</summary>';Admin::quiz_meta($item?:new \WP_Post((object)['ID'=>0,'post_type'=>'nexo_quiz']));echo '</details>'.Portal::button('Salvar conteúdo').'</form></section>';return;
        }
        echo '<div class="np-section-actions"><h2>'.esc_html($p->post_title).'</h2><a class="np-button" href="'.esc_url(Portal::url('content',['course_id'=>$course,'editor'=>'new'])).'">＋ Adicionar conteúdo</a></div><div class="np-stack">';
        $items=get_posts(['post_type'=>array_keys(self::TYPES),'post_status'=>['publish','draft','private'],'numberposts'=>-1,'meta_key'=>'_nexo_course_id','meta_value'=>$course,'orderby'=>['menu_order'=>'ASC','ID'=>'ASC']]);
        foreach($items as $it){echo '<article class="np-card np-row"><div><span class="np-badge">'.esc_html(self::TYPES[$it->post_type]).' · '.esc_html($it->post_status==='publish'?'Publicado':'Rascunho').'</span><h3>'.esc_html($it->post_title).'</h3></div><div class="np-actions"><a class="np-button np-secondary" href="'.esc_url(Portal::url('content',['course_id'=>$course,'item_id'=>$it->ID,'editor'=>'edit'])).'">Editar</a>'.Portal::form('content_archive','content',['course_id'=>$course,'item_id'=>$it->ID]).Portal::button('Rascunho','np-quiet').'</form></div></article>';}
        echo '</div>';if(!$items){echo '<p class="np-empty">Este curso ainda não tem conteúdos. Eles são opcionais.</p>';}
    }
}
